mapper.select:
select count(distinct(ip))
from link_access_log
where link_id=#{linkId,jdbcType=BIGINT}

select count(distinct(ip))
from link_access_log
where link_id=#{linkId,jdbcType=BIGINT}
and access_time >= #{minAccessTime,jdbcType=TIMESTAMP}
and access_time < #{maxAccessTime,jdbcType=TIMESTAMP}

select count(*) as pv, count(distinct(ip)) as uv, date_format(access_time, '%Y-%m-%d %H') as hour
from link_access_log
where link_id=#{linkId,jdbcType=BIGINT}
and access_time >= #{minAccessTime,jdbcType=TIMESTAMP}
and access_time < #{maxAccessTime,jdbcType=TIMESTAMP}
group by hour
order by hour
